package main
import("image";"image/draw";"image/gif";"image/png";"os";"fmt";"encoding/json";"strconv")
func main(){f,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};g,e:=gif.DecodeAll(f);if e!=nil{panic(e)};f.Close();canvas:=image.NewRGBA(image.Rect(0,0,g.Config.Width,g.Config.Height));frame:=len(g.Image)/2;if len(os.Args)>3{frame,e=strconv.Atoi(os.Args[3]);if e!=nil||frame<0||frame>=len(g.Image){panic("invalid frame")}};for i:=0;i<=frame;i++{draw.Draw(canvas,g.Image[i].Bounds(),g.Image[i],g.Image[i].Bounds().Min,draw.Over)};o,e:=os.Create(os.Args[2]);if e!=nil{panic(e)};if e=png.Encode(o,canvas);e!=nil{panic(e)};o.Close();m:=map[string]any{"gif":os.Args[1],"width":g.Config.Width,"height":g.Config.Height,"decoded_frames":len(g.Image),"png_frame":frame,"all_frames_decoded":true};b,_:=json.Marshal(m);fmt.Println(string(b))}
